window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-1cc72096a5061397"]={"versions": [{"id": "FIG-1cc72096a5061397", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Definition des ECU-Konfigurationsmodells (ECUC) für den Diagnostic Event Manager (Dem) in der AUTOSAR Classic Platform. Das Diagramm spezifiziert die Metamodell-Struktur für die Zuordnung von Enable Conditions zu diagnostischen Events über Condition-Gruppen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Konfigurations-Container und Parameter:</p>\n<ul class=\"fig-list\"><li><code>DemGeneral</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 1..1): Haupt-Konfigurationscontainer, der Sub-Container aggregiert.\n</li><li><code>DemEnableConditionGroup</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 0..255): Sub-Container von <code>DemGeneral</code>, repräsentiert eine Gruppierung von Aktivierungsbedingungen.\n</li><li><code>DemEnableCondition</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 0..255): Sub-Container von <code>DemGeneral</code>, definiert eine einzelne Aktivierungsbedingung.\n</li><li><code>DemEnableConditionId</code> (<code>EcucIntegerParamDef</code>, Multiplizität 1..1): Parameter innerhalb von <code>DemEnableCondition</code>, Wertebereich min = 0 bis max = 255, <code>symbolicNameValue = true</code>.\n</li><li><code>DemEnableConditionStatus</code> (<code>EcucBooleanParamDef</code>, Multiplizität 1..1): Boolescher Parameter innerhalb von <code>DemEnableCondition</code>.\n</li><li><code>DemEnableConditionRef</code> (<code>EcucReferenceDef</code>, Multiplizität 1..255): Referenz innerhalb von <code>DemEnableConditionGroup</code> mit Ziel (<code>+destination</code>) auf <code>DemEnableCondition</code>.\n</li><li><code>DemEventParameter</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 1..65535): Container für diagnostische Ereignisse.\n</li><li><code>DemEnableConditionGroupRef</code> (<code>EcucReferenceDef</code>, Multiplizität 0..1): Optionale Referenz innerhalb von <code>DemEventParameter</code> mit Ziel (<code>+destination</code>) auf <code>DemEnableConditionGroup</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Konfigurationsdiagramm ohne dynamische Ablauf- oder Sequenzinteraktionen zur Laufzeit. Es bildet die strukturellen Abhängigkeiten ab: Ein <code>DemEventParameter</code> kann maximal einer <code>DemEnableConditionGroup</code> zugeordnet werden (<code>DemEnableConditionGroupRef</code>), welche wiederum 1 bis 255 einzelne Bedingungen (<code>DemEnableCondition</code>) über <code>DemEnableConditionRef</code> bündelt. Jede <code>DemEnableCondition</code> besitzt eine eindeutige ID sowie einen Initialstatus.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgabe für den BSW-Generator und Konfigurationseditoren des Dem-Moduls gemäß AUTOSAR-Metamodell. Konfigurationswerkzeuge müssen sicherstellen, dass:</p>\n<ul class=\"fig-list\"><li>Bis zu 255 <code>DemEnableCondition</code>- und <code>DemEnableConditionGroup</code>-Container unter <code>DemGeneral</code> instanziiert werden können.\n</li><li>Jede Gruppe mindestens eine und maximal 255 Referenzen auf bestehende <code>DemEnableCondition</code>-Container enthält.\n</li><li>Events optional höchstens eine Gruppe referenzieren (Kardinalität 0..1).\n</li><li><code>DemEnableConditionId</code> als symbolischer Name generiert wird und im Wertebereich [0, 255] liegt.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-38311e5d6673403a", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Definition des ECU-Konfigurationsmodells (ECUC) für den Diagnostic Event Manager (Dem) in der AUTOSAR Classic Platform. Das Diagramm spezifiziert die Metamodell-Struktur für die Zuordnung von Enable Conditions zu diagnostischen Events über Condition-Gruppen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Konfigurations-Container und Parameter:</p>\n<ul class=\"fig-list\"><li><code>DemGeneral</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 1..1): Haupt-Konfigurationscontainer, der Sub-Container aggregiert.\n</li><li><code>DemEnableConditionGroup</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 0..255): Sub-Container von <code>DemGeneral</code>, repräsentiert eine Gruppierung von Aktivierungsbedingungen.\n</li><li><code>DemEnableCondition</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 0..255): Sub-Container von <code>DemGeneral</code>, definiert eine einzelne Aktivierungsbedingung.\n</li><li><code>DemEnableConditionId</code> (<code>EcucIntegerParamDef</code>, Multiplizität 1..1): Parameter innerhalb von <code>DemEnableCondition</code>, Wertebereich min = 0 bis max = 255, <code>symbolicNameValue = true</code>.\n</li><li><code>DemEnableConditionStatus</code> (<code>EcucBooleanParamDef</code>, Multiplizität 1..1): Boolescher Parameter innerhalb von <code>DemEnableCondition</code>.\n</li><li><code>DemEnableConditionRef</code> (<code>EcucReferenceDef</code>, Multiplizität 1..255): Referenz innerhalb von <code>DemEnableConditionGroup</code> mit Ziel (<code>+destination</code>) auf <code>DemEnableCondition</code>.\n</li><li><code>DemEventParameter</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 1..65535): Container für diagnostische Ereignisse.\n</li><li><code>DemEnableConditionGroupRef</code> (<code>EcucReferenceDef</code>, Multiplizität 0..1): Optionale Referenz innerhalb von <code>DemEventParameter</code> mit Ziel (<code>+destination</code>) auf <code>DemEnableConditionGroup</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Konfigurationsdiagramm ohne dynamische Ablauf- oder Sequenzinteraktionen zur Laufzeit. Es bildet die strukturellen Abhängigkeiten ab: Ein <code>DemEventParameter</code> kann maximal einer <code>DemEnableConditionGroup</code> zugeordnet werden (<code>DemEnableConditionGroupRef</code>), welche wiederum 1 bis 255 einzelne Bedingungen (<code>DemEnableCondition</code>) über <code>DemEnableConditionRef</code> bündelt. Jede <code>DemEnableCondition</code> besitzt eine eindeutige ID sowie einen Initialstatus.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgabe für den BSW-Generator und Konfigurationseditoren des Dem-Moduls gemäß AUTOSAR-Metamodell. Konfigurationswerkzeuge müssen sicherstellen, dass:</p>\n<ul class=\"fig-list\"><li>Bis zu 255 <code>DemEnableCondition</code>- und <code>DemEnableConditionGroup</code>-Container unter <code>DemGeneral</code> instanziiert werden können.\n</li><li>Jede Gruppe mindestens eine und maximal 255 Referenzen auf bestehende <code>DemEnableCondition</code>-Container enthält.\n</li><li>Events optional höchstens eine Gruppe referenzieren (Kardinalität 0..1).\n</li><li><code>DemEnableConditionId</code> als symbolischer Name generiert wird und im Wertebereich [0, 255] liegt.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-1cc72096a5061397", "to": "FIG-38311e5d6673403a", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
